import sys
import math

def main():
    import sys
    import math

    def read_ints():
        return map(int, sys.stdin.readline().split())

    x1, y1, x2, y2 = read_ints()
    vmax, t = read_ints()
    vx1, vy1 = read_ints()
    vx2, vy2 = read_ints()

    def distance(x1, y1, x2, y2):
        return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

    def time_to_reach(x1, y1, x2, y2, vx, vy, vmax):
        dx = x2 - x1
        dy = y2 - y1
        d = distance(dx, dy, 0, 0)
        if d == 0:
            return 0
        v = math.sqrt(vx ** 2 + vy ** 2)
        if v == 0:
            return d / vmax
        cos_theta = (vx * dx + vy * dy) / (v * d)
        if cos_theta >= 1:
            return d / vmax
        elif cos_theta <= -1:
            return float('inf')
        else:
            t1 = math.acos(cos_theta) / (2 * math.pi) * t
            t2 = (d - v * t1) / vmax
            return t1 + t2

    t1 = time_to_reach(x1, y1, x1 + vx1 * t, y1 + vy1 * t, vx1, vy1, vmax)
    t2 = time_to_reach(x1 + vx1 * t, y1 + vy1 * t, x2, y2, vx2, vy2, vmax)
    print(t1 + t2)

if __name__ == "__main__":
    main()
